            --card-bg: #ffffff;

            --text-primary: #212529;

            --text-secondary: #6c757d;

            --accent: #2563eb;

            --accent-hover: #1d4ed8;

            --risk-low: #16a34a;

            --risk-medium: #ca8a04;

