        }

        details summary { cursor: pointer; font-weight: 600; color: var(--accent); outline: none; }

        details p { margin-top: 10px; color: var(--text-primary); }



        .tabs { display: flex; gap: 10px; margin-bottom: 20px; border-bottom: 1px solid var(--border); }

        .tab-btn {

