<script>

    // --- STATE MANAGEMENT ---

    let claims = [];

    let currentIndex = 0;



    // --- INITIALIZATION ---

    document.addEventListener('DOMContentLoaded', () => {

        const stored = localStorage.getItem('research_claims');

        if (stored) {

            try {

                claims = JSON.parse(stored);

            } catch (e) {

                claims = [];

            }

        }

        attachEventListeners();

    });



    function attachEventListeners() {

        // Form submission

        document.getElementById('claimForm').addEventListener('submit', handleSubmit);



        // Tab switching

        document.querySelectorAll('.tab-btn').forEach(btn => {

            btn.addEventListener('click', (e) => switchTab(e.target.dataset.tab));

        });



        // Flipbook controls

        document.getElementById('sortRiskToggle').addEventListener('change', () => {

            currentIndex = 0;

            renderFlipbook();

        });

        document.getElementById('clearAllBtn').addEventListener('click', clearAllData);

        document.getElementById('prevBtn').addEventListener('click', () => navigate(-1));

        document.getElementById('nextBtn').addEventListener('click', () => navigate(1));



        // Export controls

        document.getElementById('regenBtn').addEventListener('click', generateExport);

        document.getElementById('copyBtn').addEventListener('click', copyToClipboard);

    }



    // --- TAB SWITCHING ---

    function switchTab(tabName) {

        document.querySelectorAll('.tab-content').forEach(el => el.classList.remove('active'));

        document.querySelectorAll('.tab-btn').forEach(el => el.classList.remove('active'));



        document.getElementById(`tab-${tabName}`).classList.add('active');

        document.querySelector(`.tab-btn[data-tab="${tabName}"]`).classList.add('active');



        if (tabName === 'flipbook') {

            currentIndex = 0;

            renderFlipbook();

        }

        if (tabName === 'export') {

            generateExport();

        }

    }



    // --- RISK CALCULATION ---

    function calculateRisk(pubDateStr, evidenceType) {

        const pubDate = new Date(pubDateStr);

        const now = new Date();

        const yearsOld = (now - pubDate) / (1000 * 60 * 60 * 24 * 365.25);



        let agePenalty = 0;

        let freshnessWarning = null;

        let warningClass = 'safe';



        if (yearsOld > 5) {

            agePenalty = 2;

            freshnessWarning = "Critical: Source is over 5 years old. Verify if newer data supersedes this.";

            warningClass = 'critical';

        } else if (yearsOld > 2) {

            agePenalty = 1;

            freshnessWarning = "Warning: Source is 2-5 years old. Consider checking for recent updates.";

            warningClass = 'warn';

        } else {

            freshnessWarning = `Source is fresh (${yearsOld.toFixed(1)} years old).`;

        }



        const evidenceScores = {

            'meta-analysis': 0,

            'rct': 1,

            'observational': 2,

            'expert': 3,

            'anecdotal': 4

        };

        const evidencePenalty = evidenceScores[evidenceType] !== undefined ? evidenceScores[evidenceType] : 4;

        const totalRisk = agePenalty + evidencePenalty;



        let riskLevel = 'low';

        if (totalRisk >= 4) riskLevel = 'high';

        else if (totalRisk >= 2) riskLevel = 'medium';



        return { totalRisk, riskLevel, yearsOld: yearsOld.toFixed(1), freshnessWarning, warningClass };

    }



    // --- FORM HANDLING ---

    function handleSubmit(e) {

        e.preventDefault();



        const claim = document.getElementById('claimInput').value.trim();

        const source = document.getElementById('sourceInput').value.trim();

        const pubDate = document.getElementById('pubDateInput').value;

        const evidenceType = document.getElementById('evidenceTypeInput').value;

        const notes = document.getElementById('notesInput').value.trim();



        const riskData = calculateRisk(pubDate, evidenceType);



        const newClaim = {

            id: Date.now(),

            claim,

            source,

            pubDate,

            evidenceType,

            notes,

            riskScore: riskData.totalRisk,

            riskLevel: riskData.riskLevel,

            freshnessWarning: riskData.freshnessWarning,

            warningClass: riskData.warningClass,

            yearsOld: riskData.yearsOld

        };



        claims.push(newClaim);

        saveData();



        e.target.reset();

        document.getElementById('claimInput').focus();

        alert('Claim added successfully! Switch to the "Review Flipbook" tab to view it.');

    }



    function saveData() {

        localStorage.setItem('research_claims', JSON.stringify(claims));

    }



    function clearAllData() {

        if (claims.length === 0) return;

        if (confirm('Are you sure you want to delete all claims? This cannot be undone.')) {

            claims = [];

            currentIndex = 0;

            saveData();

            renderFlipbook();

        }

    }



    // --- FLIPBOOK RENDERING (SAFE DOM MANIPULATION) ---

    function getSortedClaims() {

        const sortRisk = document.getElementById('sortRiskToggle').checked;

        if (sortRisk) {

            return [...claims].sort((a, b) => b.riskScore - a.riskScore);

        }

        return claims;

    }



    function renderFlipbook() {

        const container = document.getElementById('cardContainer');

        const nav = document.getElementById('cardNav');

        const counter = document.getElementById('cardCounter');

        const sortedClaims = getSortedClaims();



        container.innerHTML = ''; // Clear existing safe nodes



        if (sortedClaims.length === 0) {

            const emptyDiv = document.createElement('div');

            emptyDiv.className = 'empty-state';



            const h3 = document.createElement('h3');

            h3.textContent = 'No claims added yet.';



            const p = document.createElement('p');

            p.textContent = 'Go to the "Add Claims" tab to paste your first research claim.';



            emptyDiv.appendChild(h3);

            emptyDiv.appendChild(p);

            container.appendChild(emptyDiv);



            nav.style.display = 'none';

            counter.textContent = '0 / 0';

            return;

        }



        if (currentIndex >= sortedClaims.length) currentIndex = sortedClaims.length - 1;

        if (currentIndex < 0) currentIndex = 0;



        const item = sortedClaims[currentIndex];

        counter.textContent = `${currentIndex + 1} / ${sortedClaims.length}`;

        nav.style.display = 'flex';



        const evidenceLabels = {

            'meta-analysis': 'Meta-Analysis / Systematic Review',

            'rct': 'Randomized Controlled Trial (RCT)',

            'observational': 'Observational / Cohort Study',

            'expert': 'Expert Opinion / Editorial',

            'anecdotal': 'Anecdotal / Unknown / Blog'

        };



        // Build Card Safely

        const card = document.createElement('div');

        card.className = `flip-card risk-${item.riskLevel}`;



        // Header

        const header = document.createElement('div');

        header.className = 'card-header';



        const badge = document.createElement('span');

        badge.className = 'risk-badge';

        badge.textContent = `Risk: ${item.riskLevel.toUpperCase()} (Score: ${item.riskScore})`;

        header.appendChild(badge);



        const delBtn = document.createElement('button');

        delBtn.className = 'btn btn-danger';

        delBtn.style.padding = '4px 10px';

        delBtn.style.fontSize = '0.8rem';

        delBtn.textContent = 'Delete';

        delBtn.addEventListener('click', () => deleteClaim(item.id));

        header.appendChild(delBtn);

        card.appendChild(header);



        // Claim Text

        const claimText = document.createElement('div');

        claimText.className = 'claim-text';

        claimText.textContent = `"${item.claim}"`;

        card.appendChild(claimText);



        // Meta Grid

        const metaGrid = document.createElement('div');

        metaGrid.className = 'meta-grid';



        const createMetaItem = (label, value) => {

            const div = document.createElement('div');

            div.className = 'meta-item';

            const strong = document.createElement('strong');

            strong.textContent = label;

            div.appendChild(strong);

            const span = document.createElement('span');

            span.textContent = value;

            div.appendChild(span);

            return div;

        };



        const formattedDate = new Date(item.pubDate).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });



        metaGrid.appendChild(createMetaItem('Source', item.source));

        metaGrid.appendChild(createMetaItem('Evidence Type', evidenceLabels[item.evidenceType] || item.evidenceType));

        metaGrid.appendChild(createMetaItem('Publication Date', formattedDate));

        metaGrid.appendChild(createMetaItem('Age', `${item.yearsOld} years`));

        card.appendChild(metaGrid);



        // Freshness Warning

        const warningDiv = document.createElement('div');

        warningDiv.className = `freshness-warning ${item.warningClass}`;

        warningDiv.textContent = item.warningClass === 'safe' ? `✅ ${item.freshnessWarning}` : `⚠️ ${item.freshnessWarning}`;

        card.appendChild(warningDiv);



        // Notes (if exists)

        if (item.notes && item.notes.trim() !== '') {

            const notesDiv = document.createElement('div');

            notesDiv.style.marginTop = '20px';

            notesDiv.style.paddingTop = '15px';

            notesDiv.style.borderTop = '1px dashed var(--border)';



            const notesStrong = document.createElement('strong');

            notesStrong.textContent = 'Editor Notes: ';

            notesDiv.appendChild(notesStrong);



            const notesSpan = document.createElement('span');

            notesSpan.textContent = item.notes;

            notesDiv.appendChild(notesSpan);



            card.appendChild(notesDiv);

        }



        // Apply animation class

        card.style.opacity = '0';

        card.style.transform = 'translateY(10px)';

        container.appendChild(card);



        // Trigger reflow for animation

        void card.offsetWidth;

        card.style.opacity = '1';

        card.style.transform = 'translateY(0)';

    }



    function navigate(direction) {

        const sortedClaims = getSortedClaims();

        const newIndex = currentIndex + direction;



        if (newIndex >= 0 && newIndex < sortedClaims.length) {

            currentIndex = newIndex;

            renderFlipbook();

        }

    }



    function deleteClaim(id) {

        if (confirm('Delete this claim?')) {

            claims = claims.filter(c => c.id !== id);

            if (currentIndex >= claims.length) {

                currentIndex = Math.max(0, claims.length - 1);

            }

            saveData();

            renderFlipbook();

        }

    }



    // --- EXPORT HANDOFF ---

    function generateExport() {

        const sortedClaims = getSortedClaims();

        const exportTextarea = document.getElementById('exportText');



        if (sortedClaims.length === 0) {

            exportTextarea.value = 'No claims to export.';

            return;

        }



        const sortOrder = document.getElementById('sortRiskToggle').checked ? 'Highest Risk First' : 'Chronological (Added)';

        let output = `# RESEARCH CLAIMS HANDOFF\n`;

        output += `Generated: ${new Date().toLocaleString()}\n`;

        output += `Total Claims: ${sortedClaims.length}\n`;

        output += `Sort Order: ${sortOrder}\n\n`;

        output += `---\n\n`;



        sortedClaims.forEach((item, index) => {

            output += `### Claim ${index + 1} [${item.riskLevel.toUpperCase()} RISK]\n`;

            output += `**Claim:** "${item.claim}"\n`;

            output += `**Source:** ${item.source}\n`;

            output += `**Date:** ${item.pubDate} (${item.yearsOld} years old)\n`;

            output += `**Evidence:** ${item.evidenceType}\n`;

            if (item.freshnessWarning && item.warningClass !== 'safe') {

                output += `**⚠️ Freshness Note:** ${item.freshnessWarning}\n`;

            }

            if (item.notes) {

                output += `**Editor Notes:** ${item.notes}\n`;

            }

            output += `\n`;

        });



        exportTextarea.value = output;

    }



    function copyToClipboard() {

        const exportTextarea = document.getElementById('exportText');

        exportTextarea.select();

        exportTextarea.setSelectionRange(0, 99999); // For mobile devices



        navigator.clipboard.writeText(exportTextarea.value).then(() => {

            const feedback = document.getElementById('copyFeedback');

            feedback.style.opacity = '1';

            setTimeout(() => { feedback.style.opacity = '0'; }, 2000);

        }).catch(err => {

            alert('Failed to copy automatically. Please select the text and copy manually.');

        });

    }

</script>



